import{_ as r,C as n,c as i,o as d,a3 as l,G as s,j as o,a}from"./chunks/framework.Dokpd4od.js";const T=JSON.parse('{"title":"My allocation","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/allocations/my-allocation.md","filePath":"master/human-resources/time-off/allocations/my-allocation.md","lastUpdated":1793074831000}'),m={name:"master/human-resources/time-off/allocations/my-allocation.md"};function c(p,e,u,g,y,f){const t=n("ImagePopup");return d(),i("div",null,[e[0]||(e[0]=l('<h1 id="my-allocation" tabindex="-1">My allocation <a class="header-anchor" href="#my-allocation" aria-label="Permalink to &quot;My allocation&quot;">​</a></h1><p>My Allocation lists the day balances granted to you and lets you ask for more days. You use it when a leave type needs an allocation and you want to request days yourself. Aureus fills in the employee for you.</p><blockquote><p><strong>In simple words:</strong> Open My Allocation, fill a short form, and wait for approval. Approved days appear on your balance cards.</p></blockquote><p>Open <code>Time Off → My Time → My Allocation</code>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>The leave type must exist. See <a href="./../setup/time-off-types.html">Leave types</a>. Your user also needs a linked employee.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page is titled <strong>My Allocations</strong>. Each row shows one allocation.</p><ul><li><strong><em>Time Off Type:</em></strong> The kind of leave, for example <strong>Paid Time Off</strong>.</li><li><strong><em>Amount:</em></strong> The number of days, for example <code>20.0000</code>. The form calls this field <strong>Allocation</strong>.</li><li><strong><em>Allocation Type:</em></strong> Shows <strong>Regular</strong>.</li><li><strong><em>Status:</em></strong> <strong>To Approve</strong>, <strong>Approved</strong> or <strong>Refused</strong>.</li></ul><p>Use <strong>Group by</strong> to group rows by <strong>Employee Name</strong>, <strong>Time Off Type</strong>, <strong>Allocation Type</strong>, <strong>Status</strong> or <strong>Start Date</strong>. Type in the search box to find a row.</p>',9)),s(t,{src:"/images1/time-off/alloc_my_list.png",alt:"My Allocations list with one row: Paid Time Off, 20.0000, Regular, Approved"}),e[1]||(e[1]=o("h2",{id:"request-an-allocation",tabindex:"-1"},[a("Request an allocation "),o("a",{class:"header-anchor",href:"#request-an-allocation","aria-label":'Permalink to "Request an allocation"'},"​")],-1)),e[2]||(e[2]=o("ol",null,[o("li",null,[a("Open "),o("code",null,"Time Off → My Time → My Allocation"),a(". Click "),o("strong",null,"New My Allocation"),a(".")])],-1)),s(t,{src:"/images1/time-off/alloc_my_create_empty.png",alt:"Create My Allocation form with the State bar on To Approve, empty Name and Time Off Type, Regular selected, Date From Oct 26 2026, Date To No Limit and Allocation 0"}),e[3]||(e[3]=l('<ol start="2"><li>Look at the <strong>State</strong> bar. It starts on <strong>To Approve</strong>. You cannot change it.</li></ol><h3 id="allocation-details" tabindex="-1">Allocation details <a class="header-anchor" href="#allocation-details" aria-label="Permalink to &quot;Allocation details&quot;">​</a></h3><ol start="3"><li>Type a <strong>Name</strong>. Type <code>Annual leave 2026 top-up</code>.</li><li>Choose a <strong>Time Off Type</strong>, for example <strong>Paid Time Off</strong>.</li><li>Leave <strong>Allocation Type</strong> on <strong>Regular</strong>.</li></ol><ul><li><strong><em>Name:</em></strong> Required. A short label for the allocation.</li><li><strong><em>Time Off Type:</em></strong> Required. The leave type that receives the days.</li><li><strong><em>Allocation Type:</em></strong> Required. Keep <strong>Regular</strong>.</li></ul><h3 id="validity-period" tabindex="-1">Validity period <a class="header-anchor" href="#validity-period" aria-label="Permalink to &quot;Validity period&quot;">​</a></h3><ol start="6"><li>Check <strong>Date From</strong>. It is today by default. Change it if the days start later.</li><li>Leave <strong>Date To</strong> empty for an open ended allocation. The field shows <strong>No Limit</strong>.</li></ol><ul><li><strong><em>Date From:</em></strong> Required. The first day the allocation is valid.</li><li><strong><em>Date To:</em></strong> Optional. The last valid day. Leave it empty to keep the allocation open ended.</li></ul><h3 id="days-and-reason" tabindex="-1">Days and reason <a class="header-anchor" href="#days-and-reason" aria-label="Permalink to &quot;Days and reason&quot;">​</a></h3><ol start="8"><li>Type the number of days in <strong>Allocation</strong>. The field shows <strong>Number of Days</strong>. Type <code>5</code>.</li><li>Explain the request in <strong>Reason</strong>. Type <code>Extra days for a family trip</code>.</li></ol><ul><li><strong><em>Allocation:</em></strong> Required. The number of days. The default is 0.</li><li><strong><em>Reason:</em></strong> Optional. Tell the approver why you need the days.</li></ul>',10)),s(t,{src:"/images1/time-off/alloc_my_create_filled.png",alt:"Filled Create My Allocation form: Name Annual leave 2026 top-up, Paid Time Off, Regular, Date From Oct 26 2026, Date To No Limit, 5 days, reason Extra days for a family trip"}),e[4]||(e[4]=l('<ol start="10"><li>Click <strong>Create</strong>. Click <strong>Create &amp; create another</strong> to add a second one.</li></ol><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>A new allocation gets the status <strong>To Approve</strong>. It adds nothing to your balance yet. A manager approves it in <a href="./manage-allocations.html">Manage allocations</a>. Then the status becomes <strong>Approved</strong>. The days then count on your balance card.</p><p>A manager can also refuse it. A refused allocation never adds days.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Your user must be linked to an employee. Without one, Aureus asks you to contact your administrator.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Time off allocations</a></li><li><a href="./manage-allocations.html">Manage allocations</a></li><li><a href="./../requests/my-time.html">My Time dashboard</a></li><li><a href="./../setup/time-off-types.html">Leave types</a></li></ul>',7))])}const A=r(m,[["render",c]]);export{T as __pageData,A as default};
